inline bool VerifyBufferRef(::flatbuffers::Verifier &verifier, const void *obj, BufferRef type) {
  switch (type) {
    case BufferRef::NONE: {
      return true;
    }
    case BufferRef::ArgumentRef: {
      auto ptr = reinterpret_cast<const fbs::ArgumentRef *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case BufferRef::PatchRef: {
      auto ptr = reinterpret_cast<const fbs::PatchRef *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyBufferRefVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<BufferRef> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyBufferRef(
        verifier,  values->Get(i), types->GetEnum<BufferRef>(i))) {
      return false;
    }
  }
  return true;
}

