inline bool VerifyTrigger(::flatbuffers::Verifier &verifier, const void *obj, Trigger type) {
  switch (type) {
    case Trigger::NONE: {
      return true;
    }
    case Trigger::ImmediateTrigger: {
      auto ptr = reinterpret_cast<const fbs::ImmediateTrigger *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Trigger::AfterDriverEntryTrigger: {
      auto ptr = reinterpret_cast<const fbs::AfterDriverEntryTrigger *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyTriggerVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<Trigger> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyTrigger(
        verifier,  values->Get(i), types->GetEnum<Trigger>(i))) {
      return false;
    }
  }
  return true;
}

