inline const fbs::Event *GetEvent(const void *buf) {
  return ::flatbuffers::GetRoot<fbs::Event>(buf);
}

inline const fbs::Event *GetSizePrefixedEvent(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<fbs::Event>(buf);
}

inline bool VerifyEventBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<fbs::Event>(nullptr);
}

inline bool VerifySizePrefixedEventBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<fbs::Event>(nullptr);
}

inline void FinishEventBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<fbs::Event> root) {
  fbb.Finish(root);
}

inline void FinishSizePrefixedEventBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<fbs::Event> root) {
  fbb.FinishSizePrefixed(root);
}

inline std::unique_ptr<fbs::EventT> UnPackEvent(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<fbs::EventT>(GetEvent(buf)->UnPack(res));
}

inline std::unique_ptr<fbs::EventT> UnPackSizePrefixedEvent(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<fbs::EventT>(GetSizePrefixedEvent(buf)->UnPack(res));
}

